  dict(id='ck6', group='Points and bookings', text='Book the Brisbane → Sydney feeder on a QF flight landing by 3pm AEDT (cash ~A$140 or 9,200 pts + A$58)', due='2026-10-20', notes='Same day, separate ticket. Consider the 9,200-point reward if you still have plenty left after the homeward booking.'),
