  dict(id='ck15', group='Before you go', text='Book ski rental online (village shop) for Fri 12, Sat 13 and Mon 15 Feb with your boot size in cm; include ski wear if travelling light', due='2027-01-15', notes='Big boot sizes run out in peak weeks. Pick a shop that opens by 7:45 so Friday is not lost.'),
  dict(id='ck16', group='Packing', text='Ski: thermals, mid-layer, gloves, goggles, beanie, buff, ski socks x3 (rent jacket/pants/skis/boots/helmet)', due='2027-02-06'),
  dict(id='ck17', group='Packing', text='Onsen kit: small towel, plus a sense of humour about being naked with strangers', due='2027-02-06'),
