  dict(id='ck19', group='In Japan', text='USJ: through the gate, open the app, claim Super Nintendo World timed entry within seconds (or use the Express Pass slot)', due='2027-02-10'),
  dict(id='ck20', group='In Japan', text='Keep the N’EX round-trip ticket somewhere safe for the trip back to Narita', due='2027-02-09'),
  dict(id='ck23', group='In Japan', text='Tax-free shopping is now a refund at the airport (from Nov 2026): pay the 10% tax at the till, keep receipts and passport scans, and allow time at Narita to claim it back on Nintendo World or Osaka souvenirs', due='2027-02-15'),
  dict(id='ck24', group='Before you go', text='Open the Qantas app → Complimentary Lounge Invitations and confirm the Titanium First Lounge invitations show with an expiry after 8 Feb 2027', due='2026-09-30', notes='They renew each card anniversary. If the current pair expires before February, the next pair will be issued on the anniversary; check which.'),
  dict(id='ck25', group='Points and bookings', text='Ask the Nozawa lodging (when booking) whether they accept a courier parcel before arrival, and get their address in Japanese for the takkyubin slip', due='2026-10-31'),
