questions = [
  dict(id='q1', question='Ski base: Nozawa Onsen, Myoko (Akakura Onsen) or Hakuba?', why='You said “south island”, which does not exist for skiing (Japan’s ski areas are on Hokkaido in the north and in the Nagano/Niigata mountains on the main island). Given Narita arrival + Osaka + a week, Nagano/Niigata is the only sensible region. Nozawa is the closest thing to Banff: a real village, walkable, hot springs, mountain rising straight off it, local food. It is also the most Australian of the villages and the busiest over the 11-14 Feb long weekend.', options=['Nozawa Onsen (planned): Banff-like village, big mountain, local food, busiest and priciest of the three that weekend', 'Myoko / Akakura Onsen: quieter, cheaper, more Japanese, 13-16 m of snow, smaller mountain, fiddlier buses', 'Hakuba: biggest terrain and most Banff-like scale, but a sprawl of villages linked by buses and very international'], recommendation='Nozawa Onsen. If you decide “not hyped” matters more than terrain, switch to Myoko: the plan only changes at the Nagano end (Shinkansen to Joetsu-Myoko instead of Iiyama).', answer='', resolved=False),
  dict(id='q2', question='Trip shape: Universal Studios first (Wednesday) or ski first and fly home from Osaka?', why='Wed 10 Feb is the only calm weekday for USJ in the window (Thu 11 is a public holiday and the weekend follows, plus the tail of Lunar New Year travel). That forces the skiing onto the long weekend. The alternative is ski Wed-Fri (quieter slopes on Wed), then USJ on Mon 15 and fly Jetstar Osaka → Brisbane at 9:45pm that night, no Tokyo backtrack.', options=['USJ Wed 10, ski Fri-Mon, fly QF62 Narita → Brisbane Mon 15 (planned)', 'Ski Wed-Fri, Osaka Sat-Mon, USJ Mon 15, Jetstar JQ24 Osaka → Brisbane Mon 15 night'], recommendation='Keep USJ on the Wednesday. Super Nintendo World on a crowded day is the thing most likely to spoil the trip, and Nozawa is big enough to absorb a weekend if you start at 8:30. Monday morning skiing is the bonus.', answer='', resolved=False),
  dict(id='q3', question='Park at Brisbane or Sunshine Coast?', why='Sunshine Coast is closer (1 h vs 1h45) and parking is ~A$20 cheaper, but it has only 3 Qantas flights a day (a cancellation of the midday one leaves nothing that beats your 6:30pm departure) and the flight home lands at Brisbane, so you would pay A$55-85 and 2 hours for a shuttle back to the car. Brisbane wins once the return is counted.', options=['Brisbane: AIRPARK ~A$109, QF feeder with ~18 daily fallbacks, land straight at the car on 16 Feb (planned)', 'Sunshine Coast: ~A$90 parking, QF903 at 12:15 or the 7am QF905, then shuttle from Brisbane on the way home'], recommendation='Brisbane. It is cheaper overall and it protects the Business reward ticket, which is the most valuable thing in this trip.', answer='', resolved=False),
  dict(id='q4', question='How to use the points for the flight home?', why='The upgrade-to-Premium-Economy idea does not work on the Brisbane flight: QF62 is a two-class A330 with no PE cabin. The only Qantas Tokyo flight with PE leaves Haneda at 6:55am for Sydney. You have 170k points; Business on QF62 is 82,100 (confirmed price), Economy about 29,000 (estimate).', options=['Economy Classic Reward on QF62 (~29k est.) + Economy Plus extra legroom (~19.5k pts or ~A$100-150) (planned)', 'Business Classic Reward on QF62 (82,100 + ~A$300 taxes) if a seat shows', 'Jetstar JQ10 Narita → Brisbane on points (~24k est.) or cash (~A$409), bid for Jetstar Business', 'Cash economy on QF62 (~A$720) in an upgradeable fare class and hope: PE does not exist on this flight, so no'], recommendation='Search both Economy and Business Classic on 15 and 16 Feb the day the points land. Take Business if it is there; otherwise Economy Classic plus Economy Plus. Keep alerts running until departure because seats get released in batches.', answer='', resolved=False),
  dict(id='q5', question='What are the two “first class lounge passes”, exactly?', why='Answered: they are Qantas Money Titanium card First Lounge invitations. Valid at the Sydney, Melbourne and LA First Lounges on a QF/JQ flight, cardholder only.', options=['Use one at Melbourne T2 First Lounge on 8 Feb', 'Second one is unusable on this trip; keep it'], recommendation='Use one in Melbourne on 8 Feb; check the expiry in the Qantas app.', answer='Titanium credit card passes. One will be used in Melbourne; the other saved.', resolved=True),
  dict(id='q6', question='Rent ski gear or bring your own?', why='Rental in Nozawa is ~¥4,450-5,500 a day for skis, boots and poles, so 4 days is about A$165-200. Bringing skis means a 32 kg-allowance bag on the outbound (fine in Business) but hauling it through Tokyo Station, Osaka and two bus changes, plus the Shinkansen oversized-baggage rule.', options=['Rent everything in the village, bring only boots if you love yours (planned)', 'Bring skis and boots'], recommendation='Rent. This trip has too many trains for a ski bag. Bring your own boots only if fit is a problem for you.', answer='', resolved=False),
  dict(id='q7', question='Fly home Monday 15 or Tuesday 16 Feb?', why='Monday keeps to “about a week” and lands you home Tuesday morning. Tuesday gives a full quiet Monday on the slopes (the emptiest day) and a relaxed trip to Narita, one more night of lodging (~A$150) and a day of leave.', options=['Mon 15 Feb, QF62 21:45 (planned)', 'Tue 16 Feb, same flight, with a Monday ski day and a Narita airport hotel'], recommendation='Monday, unless the Business reward only shows on Tuesday, in which case take Tuesday and enjoy the extra ski day.', answer='', resolved=False),
  dict(id='q8', question='Keep this repo public?', why='The repo is public right now. That is why the app never writes booking references, ticket numbers or passport details to the repo (they live in the Private vault on your device). It is still safer to make the repo private since GitHub Pages works on private repos with a paid plan, or you can simply keep the rule: nothing sensitive in the plan text.', options=['Keep public, keep sensitive details in the vault only (current)', 'Make the repo private (Settings → General → Danger zone). Pages on private repos needs GitHub Pro.'], recommendation='Keep public for now and use the vault; revisit if you want to store confirmation emails in the repo.', answer='', resolved=False),
  dict(id='q10', question='Give up Sunday’s skiing for Togakushi and Zenko-ji, or fly home Tuesday to keep three full ski days?', why='You asked for a rural day and said a ski day could go. Narai-juku is now built into Thursday’s travel day at no cost. Sunday is the worst ski day (long-weekend crowds), so it is the cheapest one to trade for Togakushi’s cedar avenue and Zenko-ji. That leaves Friday, Saturday and Monday morning on skis. Flying home Tuesday 16 instead would add a full quiet Monday on the slopes for about A$150 of lodging plus a day of leave.', options=['Sunday rural day, Monday morning ski, fly Mon 15 (planned)', 'Sunday rural day and fly Tue 16 so Monday is a full ski day', 'Keep skiing Sunday; rural Japan is just the Narai stop on Thursday'], recommendation='As planned, with the powder-day escape hatch: if Sunday dawns dumping, ski and skip Togakushi.', answer='', resolved=False),
  dict(id='q11', question='Which rural stop, if you want a different one?', why='Alternatives to Togakushi from Nozawa: Obuse (30 min from Nagano by Nagaden train, chestnut sweets, the Hokusai museum, sake brewery, old streets; easy and flat) or a dawn visit to Zenko-ji’s o-asaji morning service. Shirakawa-go’s farmhouses are the postcard but are 4+ hours each way from Nozawa and heavily touristed; not worth it on this trip. Matsumoto castle is a city.', options=['Togakushi + Zenko-ji (planned): mountain shrine, cedars, soba, snow walk', 'Obuse + Zenko-ji: gentler, indoor-heavy, good if the weather is foul', 'Nothing beyond Narai'], recommendation='Togakushi, with Obuse as the bad-weather substitute.', answer='', resolved=False),
  dict(id='q9', question='Rough budget ceiling?', why='The plan currently totals roughly A$2,700-3,300 in cash on top of points, depending on Osaka hotel and the Express Pass. Knowing your ceiling decides whether to trade the ryokan half-board for a minshuku, and whether the Express Pass stays in.', options=['Under A$2,500: minshuku, skip Express Pass, Jetstar home', 'A$2,500-3,500: as planned', 'Over A$3,500: ryokan with dinner every night, Business home if available'], recommendation='As planned. The Express Pass is the one “splurge” that buys back a whole day.', answer='', resolved=False),
]

FOOD_GUIDE = [
  dict(title='How to tell a place is happy to have you', body='Green lights: a menu or prices visible outside, a ticket machine (ramen, soba, gyudon), plastic food models, a photo or English menu, a listing on Tabelog, staff who call “irasshaimase” when the door opens, and any yakiniku, okonomiyaki, udon or soba shop. Nozawa, Tenma, Fukushima, Tsuruhashi and Narai are all used to visitors; you are not intruding.'),
  dict(title='When to bow out', body='A sign reading 一見さんお断り (ichigen-san okotowari, “first-timers not accepted”) or 会員制 (members only); a tiny “snack” bar with a hostess and no price list; a six-seat counter where every seat is a regular and the master does not look up. Being turned away is not an insult: a small bow, “sumimasen”, and try the next door. That system is mostly Kyoto tea-house culture anyway; Osaka standing bars welcome anyone who orders a drink.'),
  dict(title='Manners that matter more than language', body='Order a drink first, then food. The small dish that arrives unasked (otoshi) is a cover charge, not a mistake. One drink and a couple of plates, then move on when it is crowded; angle your body to make room at a standing bar. Cash out, no tipping ever. No photos of other customers or the counter without a nod from the master. “Oishii” and “gochisosama deshita” (thanks for the meal) on the way out go a long way.'),
  dict(title='Onsen and ryokan', body='Shoes off at the genkan, slippers off on tatami. Ryokan dinner is at a set time; be there. In the bathhouses: wash sitting down before you get in, no towel in the water, no swimwear, quiet, no phones. Tattoos: Nozawa’s village bathhouses are relaxed but cover-up stickers are cheap insurance if you have visible ink.'),
]

